<script lang="ts">import {onMount} from 'svelte';import{api}from'$lib/api';import type{Student,Session}from'$lib/types';let students:Student[]=[];let sessions:Session[]=[];let records:any[]=[];let studentId='';let classSessionId='';let error='';let notice='';async function load(){try{[students,sessions]=await Promise.all([api<Student[]>('/api/students'),api<Session[]>('/api/sessions')]);if(classSessionId)records=await api<any[]>(`/api/attendance?sessionId=${classSessionId}`);}catch(e){error=e instanceof Error?e.message:'Could not load attendance.';}}async function selectSession(){records=await api<any[]>(`/api/attendance?sessionId=${classSessionId}`); }async function checkIn(){try{await api('/api/attendance',{method:'POST',body:JSON.stringify({studentId,classSessionId,notes:null})});notice='Attendance recorded.';studentId='';await selectSession();}catch(e){error=e instanceof Error?e.message:'Could not record attendance.';}}onMount(load);</script>
<div class="toolbar"><div><span class="eyebrow">MAT LOG</span><h2>Attendance check-in</h2></div></div>{#if error}<div class="error">{error}</div>{/if}{#if notice}<div class="status">{notice}</div>{/if}<section class="card"><div class="form-grid"><label>Today’s session<select bind:value={classSessionId} on:change={selectSession}><option value="" disabled>Select a session</option>{#each sessions as session}<option value={session.id}>{session.name} · {session.startTime}</option>{/each}</select></label><label>Student<select bind:value={studentId}><option value="" disabled>Select a student</option>{#each students as student}<option value={student.id}>{student.firstName} {student.lastName}</option>{/each}</select></label></div><button class="button" disabled={!classSessionId||!studentId} on:click={checkIn}>Record attendance</button></section><section class="card"><h3>Checked in</h3>{#if !classSessionId}<p class="muted">Select a session to see attendance.</p>{:else}<div class="table-wrap"><table><thead><tr><th>Student</th><th>Checked in</th></tr></thead><tbody>{#each records as record}<tr><td>{record.studentName}</td><td>{new Date(record.checkedInAtUtc).toLocaleTimeString()}</td></tr>{:else}<tr><td colspan="2" class="muted">No attendance recorded.</td></tr>{/each}</tbody></table></div>{/if}</section>
